import numpy as np

from ptm.components import PROPANE
from ptm.eos import pure_psat_newton
from ptm.fitting import aad_percent, fit_omega_mle


def test_mle_recovers_known_omega_from_synthetic_noiseless_data():
    """If the 'data' is generated by the model itself at a known omega,
    the MLE fit must recover that omega (sanity check of the optimizer
    and the likelihood setup, independent of real NIST data)."""
    true_omega = 0.18
    T = np.linspace(260, 350, 10)
    P = np.array([pure_psat_newton(PROPANE.Tc, PROPANE.Pc_Pa, true_omega, t) for t in T])

    fit = fit_omega_mle(T, P, PROPANE.Tc, PROPANE.Pc_Pa, omega0=0.1)
    assert abs(fit["omega_hat"] - true_omega) < 1e-3
    assert fit["sigma_hat"] < 1e-4  # should be ~0: noiseless synthetic data


def test_aad_percent_zero_for_self_consistent_data():
    T = np.linspace(260, 350, 8)
    P = np.array([pure_psat_newton(PROPANE.Tc, PROPANE.Pc_Pa, PROPANE.omega, t) for t in T])
    assert aad_percent(T, P, PROPANE.Tc, PROPANE.Pc_Pa, PROPANE.omega) < 1e-6
